const TZ = 'Asia/Seoul';
const event = $input.first().json;

// 봇이 보낸 메시지(다른 워크플로우의 알림 등)는 무시하여 파싱/루프를 방지한다
if (event.bot_id || event.subtype) {
  return [];
}

const text = (event.text || '').trim();

function pad(n) {
  return String(n).padStart(2, '0');
}

// KST 기준 오프셋(+09:00)을 붙인 ISO 문자열 생성
function toKSTISOString(year, month, day, hour, minute) {
  return `${year}-${pad(month)}-${pad(day)}T${pad(hour)}:${pad(minute)}:00+09:00`;
}

function getKSTNowParts() {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TZ, year: 'numeric', month: 'numeric', day: 'numeric'
  }).formatToParts(new Date()).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
  return { year: Number(parts.year), month: Number(parts.month), day: Number(parts.day) };
}

// 연도 없이 월/일만 주어진 경우: 올해 기준으로 계산하되, 이미 지난 날짜면 내년으로 이월
function resolveYear(month, day, hour, minute) {
  const now = getKSTNowParts();
  let year = now.year;
  const candidate = new Date(Date.UTC(year, month - 1, day, hour, minute));
  const nowUTC = new Date(Date.UTC(now.year, now.month - 1, now.day, 0, 0));
  if (candidate < nowUTC) {
    year += 1;
  }
  return year;
}

let match;
let year, month, day, hour, minute, title;

// 1) ISO 형식: 2026-09-10 15:30 팀 회의
match = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})\s+(\d{1,2}):(\d{2})\s+(.+)$/s);
if (match) {
  [, year, month, day, hour, minute, title] = match;
  year = Number(year); month = Number(month); day = Number(day); hour = Number(hour); minute = Number(minute);
}

// 2) 슬래시 형식: 9/10 15:30 팀 회의 (연도 없음 -> 자동 보정)
if (!match) {
  match = text.match(/^(\d{1,2})\/(\d{1,2})\s+(\d{1,2}):(\d{2})\s+(.+)$/s);
  if (match) {
    [, month, day, hour, minute, title] = match;
    month = Number(month); day = Number(day); hour = Number(hour); minute = Number(minute);
    year = resolveYear(month, day, hour, minute);
  }
}

// 3) 한국어 형식: 9월 10일 [오전|오후] 3시[30분] 팀 회의 (연도 없음 -> 자동 보정)
if (!match) {
  match = text.match(/^(\d{1,2})월\s*(\d{1,2})일\s*(오전|오후)?\s*(\d{1,2})시\s*(?:(\d{1,2})분)?\s*(.+)$/s);
  if (match) {
    let ampm, h, m;
    [, month, day, ampm, h, m, title] = match;
    month = Number(month); day = Number(day);
    h = Number(h);
    minute = m ? Number(m) : 0;
    if (ampm === '오후' && h < 12) h += 12;
    if (ampm === '오전' && h === 12) h = 0;
    hour = h;
    year = resolveYear(month, day, hour, minute);
  }
}

if (!match || !title || !title.trim()) {
  return [{
    json: {
      parsedOk: 'false',
      channel: event.channel,
      threadTs: event.ts,
      rawText: text,
      errorMessage: ':warning: 일정 형식을 확인하지 못했어요. 아래 형식으로 다시 보내주세요.\n`2026-09-10 15:30 팀 회의`\n`9/10 15:30 팀 회의`\n`9월 10일 오후 3시30분 팀 회의`'
    }
  }];
}

const startISO = toKSTISOString(year, month, day, hour, minute);
const endDate = new Date(`${startISO}`);
endDate.setUTCHours(endDate.getUTCHours() + 1);
const endISO = endDate.toISOString();

return [{
  json: {
    parsedOk: 'true',
    channel: event.channel,
    threadTs: event.ts,
    rawText: text,
    title: title.trim(),
    startISO,
    endISO,
  }
}];
